        if not circuit.measurements:
            return label
        width = QubitLane._measured_bit_count(circuit)
        bits = ["0"] * width
        for qubit, clbit in circuit.measurements:
            bits[clbit] = label[circuit.qubits - 1 - qubit]
        return "".join(reversed(bits))

